module multi_pipe_8bit #(
    parameter size = 8
) (
    input clk,
    input rst_n,
    input [size-1:0] mul_a,
    input [size-1:0] mul_b,
    input mul_en_in,
    output reg mul_en_out,
    output reg [size*2-1:0] mul_out
);

reg [size-1:0] a_reg;
reg [size-1:0] b_reg;
reg [size*2-1:0] partial_product;
reg [size*2-1:0] sum;
reg [2:0] mul_en_out_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        mul_en_out_reg <= 0;
        mul_en_out <= 0;
        mul_out <= 0;
    end else begin
        if (mul_en_in) begin
            a_reg <= mul_a;
            b_reg <= mul_b;
            partial_product <= a_reg * b_reg;
            sum <= partial_product;
            mul_en_out_reg <= {mul_en_out_reg[1:0], mul_en_in};
        end
    end
end

always @(posedge clk) begin
    if (mul_en_out_reg[2]) begin
        mul_out <= sum;
    end else begin
        mul_out <= 0;
    end
end

endmodule
